async function db(){return new Promise((resolve,reject)=>{const r=indexedDB.open('aether-unified-material-studio',1);r.onupgradeneeded=()=>{r.result.createObjectStore('graphs',{keyPath:'id'});r.result.createObjectStore('assets',{keyPath:'id'});};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
export async function storeItem(store,value){const d=await db();try{await new Promise((resolve,reject)=>{const tx=d.transaction(store,'readwrite');tx.objectStore(store).put(value);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}finally{d.close();}}
export async function getItem(store,id){const d=await db();try{return await new Promise((resolve,reject)=>{const r=d.transaction(store).objectStore(store).get(id);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}finally{d.close();}}
export async function listGraphs(){const d=await db();try{return await new Promise((resolve,reject)=>{const r=d.transaction('graphs').objectStore('graphs').getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}finally{d.close();}}
export async function removeGraph(id){const d=await db();try{await new Promise((resolve,reject)=>{const tx=d.transaction('graphs','readwrite');tx.objectStore('graphs').delete(id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}finally{d.close();}}
